package com.contextgraph.controller;

import com.contextgraph.model.*; import com.contextgraph.repository.*; import com.contextgraph.security.JwtService;
import jakarta.validation.constraints.*; import org.apache.pdfbox.Loader; import org.apache.pdfbox.text.PDFTextStripper; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
import java.nio.file.*; import java.security.MessageDigest; import java.time.Instant; import java.util.*; import java.util.stream.Collectors;
@RestController @RequestMapping("/api")
public class ApiController {
 private final UserRepository users; private final DocumentRepository docs; private final CollectionRepository collections; private final SearchRepository searches; private final PasswordEncoder encoder; private final JwtService jwt; private final Path storage;
 public ApiController(UserRepository u,DocumentRepository d,CollectionRepository c,SearchRepository s,PasswordEncoder e,JwtService j,@Value("${app.storage.directory}") String dir){users=u;docs=d;collections=c;searches=s;encoder=e;jwt=j;storage=Paths.get(dir).toAbsolutePath().normalize();}
 private AppUser current(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"User not found"));}
 private Map<String,Object> userMap(AppUser u){return Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"createdAt",u.getCreatedAt().toString());}
 private Map<String,Object> docMap(StoredDocument d){return Map.of("id",d.getId(),"name",d.getOriginalName(),"originalName",d.getOriginalName(),"sizeBytes",d.getSizeBytes(),"checksum",d.getChecksum(),"createdAt",d.getCreatedAt().toString(),"textPreview",d.getExtractedText()==null?"":d.getExtractedText().substring(0,Math.min(240,d.getExtractedText().length())));}
 public record RegisterRequest(@NotBlank @Size(max=100) String name,@Email @NotBlank String email,@NotBlank @Size(min=8,max=100) String password){}
 public record LoginRequest(@Email @NotBlank String email,@NotBlank String password){}
 @GetMapping("/health") public Map<String,Object> health(){return Map.of("status","UP","service","backend-graph","time",Instant.now().toString());}
 @PostMapping("/auth/register") public ResponseEntity<?> register(@jakarta.validation.Valid @RequestBody RegisterRequest r){String email=r.email().trim().toLowerCase(Locale.ROOT);if(users.existsByEmailIgnoreCase(email))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.CONFLICT,"An account with this email already exists");AppUser u=new AppUser();u.setName(r.name().trim());u.setEmail(email);u.setPasswordHash(encoder.encode(r.password()));users.save(u);return ResponseEntity.status(201).body(Map.of("message","Account created successfully","user",userMap(u)));}
 @PostMapping("/auth/login") public Map<String,Object> login(@jakarta.validation.Valid @RequestBody LoginRequest r){AppUser u=users.findByEmailIgnoreCase(r.email().trim()).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(r.password(),u.getPasswordHash()))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return Map.of("token",jwt.create(u.getEmail()),"user",userMap(u));}
 @GetMapping("/auth/me") public Map<String,Object> me(Authentication a){return userMap(current(a));}
 @GetMapping("/profile") public Map<String,Object> profile(Authentication a){return userMap(current(a));}
 @PatchMapping("/profile") public Map<String,Object> updateProfile(Authentication a,@RequestBody Map<String,Object> p){AppUser u=current(a);Object n=p.get("name");if(n instanceof String s&&!s.isBlank()&&s.length()<=100)u.setName(s.trim());return userMap(users.save(u));}
 @GetMapping("/documents") public List<Map<String,Object>> listDocs(Authentication a){return docs.findByOwnerIdOrderByCreatedAtDesc(current(a).getId()).stream().map(this::docMap).toList();}
 @PostMapping(value="/documents/upload",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Transactional public ResponseEntity<?> upload(Authentication a,@RequestParam("file") MultipartFile file)throws Exception{AppUser u=current(a);if(file.isEmpty())throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a PDF file");if(file.getSize()>25L*1024*1024)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Maximum upload size is 25 MB");String name=Optional.ofNullable(file.getOriginalFilename()).orElse("document.pdf");if(!name.toLowerCase(Locale.ROOT).endsWith(".pdf")&&!"application/pdf".equalsIgnoreCase(file.getContentType()))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Only PDF files are supported");byte[] bytes=file.getBytes();String checksum=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));if(docs.existsByChecksumAndOwnerId(checksum,u.getId()))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.CONFLICT,"This PDF has already been uploaded");String text;try(var pdf=Loader.loadPDF(bytes)){text=new PDFTextStripper().getText(pdf);}catch(Exception ex){throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"The uploaded file is not a readable PDF");}Files.createDirectories(storage);String stored=UUID.randomUUID()+".pdf";Files.write(storage.resolve(stored),bytes,StandardOpenOption.CREATE_NEW);StoredDocument d=new StoredDocument();d.setOwner(u);d.setOriginalName(name.replaceAll("[\\\\/\\r\\n]","_").substring(0,Math.min(240,name.length())));d.setStoredName(stored);d.setChecksum(checksum);d.setSizeBytes(bytes.length);d.setExtractedText(text);try{return ResponseEntity.status(201).body(docMap(docs.save(d)));}catch(Exception ex){Files.deleteIfExists(storage.resolve(stored));throw ex;}}
 @GetMapping("/documents/{id}") public Map<String,Object> getDoc(Authentication a,@PathVariable Long id){StoredDocument d=docs.findByIdAndOwnerId(id,current(a).getId()).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Document not found"));Map<String,Object> m=new HashMap<>(docMap(d));m.put("text",d.getExtractedText());return m;}
 @DeleteMapping("/documents/{id}") @Transactional public ResponseEntity<?> deleteDoc(Authentication a,@PathVariable Long id)throws Exception{StoredDocument d=docs.findByIdAndOwnerId(id,current(a).getId()).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Document not found"));docs.delete(d);Files.deleteIfExists(storage.resolve(d.getStoredName()).normalize());return ResponseEntity.noContent().build();}
 @GetMapping("/search") @Transactional public List<Map<String,Object>> search(Authentication a,@RequestParam(name="q",defaultValue="") String q){AppUser u=current(a);String term=q.trim();if(term.isEmpty())return List.of();searches.save(entry(u,term));return docs.findByOwnerIdAndExtractedTextContainingIgnoreCaseOrderByCreatedAtDesc(u.getId(),term).stream().map(d->{Map<String,Object> m=new HashMap<>(docMap(d));m.put("snippet",snippet(d.getExtractedText(),term));return m;}).toList();}
 private SearchEntry entry(AppUser u,String q){SearchEntry e=new SearchEntry();e.setOwner(u);e.setQuery(q.substring(0,Math.min(500,q.length())));return e;}
 private String snippet(String text,String q){if(text==null)return "";int i=text.toLowerCase(Locale.ROOT).indexOf(q.toLowerCase(Locale.ROOT));if(i<0)return text.substring(0,Math.min(220,text.length()));return text.substring(Math.max(0,i-90),Math.min(text.length(),i+q.length()+130)).replaceAll("\\s+"," ");}
 @GetMapping("/search/history") public List<Map<String,Object>> history(Authentication a){return searches.findTop30ByOwnerIdOrderByCreatedAtDesc(current(a).getId()).stream().map(s->Map.<String,Object>of("id",s.getId(),"query",s.getQuery(),"createdAt",s.getCreatedAt().toString())).toList();}
 @GetMapping("/dashboard/stats") public Map<String,Object> stats(Authentication a){AppUser u=current(a);List<StoredDocument> ds=docs.findByOwnerIdOrderByCreatedAtDesc(u.getId());return Map.of("documentCount",ds.size(),"totalDocuments",ds.size(),"totalSizeBytes",ds.stream().mapToLong(StoredDocument::getSizeBytes).sum(),"collectionCount",collections.findByOwnerIdOrderByCreatedAtDesc(u.getId()).size(),"recentDocuments",ds.stream().limit(5).map(this::docMap).toList());}
 @GetMapping("/timeline") public List<Map<String,Object>> timeline(Authentication a){return docs.findByOwnerIdOrderByCreatedAtDesc(current(a).getId()).stream().map(d->{Map<String,Object> m=new HashMap<>(docMap(d));m.put("type","document");return m;}).toList();}
 @GetMapping("/graph") public Map<String,Object> graph(Authentication a){List<StoredDocument> ds=docs.findByOwnerIdOrderByCreatedAtDesc(current(a).getId());List<Map<String,Object>> nodes=new ArrayList<>();List<Map<String,Object>> edges=new ArrayList<>();for(StoredDocument d:ds)nodes.add(Map.of("id",String.valueOf(d.getId()),"label",d.getOriginalName(),"type","document"));return Map.of("nodes",nodes,"edges",edges);}
 @GetMapping("/collections") public List<Map<String,Object>> listCollections(Authentication a){return collections.findByOwnerIdOrderByCreatedAtDesc(current(a).getId()).stream().map(c->Map.<String,Object>of("id",c.getId(),"name",c.getName(),"description",Objects.toString(c.getDescription(),""),"createdAt",c.getCreatedAt().toString())).toList();}
 @PostMapping("/collections") public ResponseEntity<?> createCollection(Authentication a,@RequestBody Map<String,Object> p){String name=Objects.toString(p.get("name"),"").trim();if(name.isEmpty()||name.length()>120)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Collection name is required (maximum 120 characters)");CollectionItem c=new CollectionItem();c.setOwner(current(a));c.setName(name);c.setDescription(Objects.toString(p.get("description"),""));c=collections.save(c);return ResponseEntity.status(201).body(Map.of("id",c.getId(),"name",c.getName(),"description",Objects.toString(c.getDescription(),""),"createdAt",c.getCreatedAt().toString()));}
 @PatchMapping("/collections/{id}") public Map<String,Object> updateCollection(Authentication a,@PathVariable Long id,@RequestBody Map<String,Object> p){CollectionItem c=collections.findByIdAndOwnerId(id,current(a).getId()).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Collection not found"));if(p.get("name") instanceof String n&&!n.isBlank()&&n.length()<=120)c.setName(n.trim());if(p.get("description") instanceof String d)c.setDescription(d);c=collections.save(c);return Map.of("id",c.getId(),"name",c.getName(),"description",Objects.toString(c.getDescription(),""),"createdAt",c.getCreatedAt().toString());}
 @DeleteMapping("/collections/{id}") public ResponseEntity<?> deleteCollection(Authentication a,@PathVariable Long id){CollectionItem c=collections.findByIdAndOwnerId(id,current(a).getId()).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Collection not found"));collections.delete(c);return ResponseEntity.noContent().build();}
 @ExceptionHandler(org.springframework.web.server.ResponseStatusException.class) public ResponseEntity<?> statusError(org.springframework.web.server.ResponseStatusException ex){return ResponseEntity.status(ex.getStatusCode()).body(Map.of("error",ex.getReason()==null?"Request failed":ex.getReason()));}
}
